function extractStartHHMM(s) {
  s = (s || '').toString().trim();
  if (!s || /low activity/i.test(s)) return '';

  // ما نعمل split على comma هنا - نأخذ أول وقت في النص
  const m = s.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?/i);
  if (!m) return '';

  let hour = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const ampm = (m[3] || (s.match(/\b(AM|PM)\b/i)?.[1]) || '').toUpperCase();

  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;

  return String(hour).padStart(2,'0') + ':' + String(min).padStart(2,'0');
}

function extractEndHHMM(s) {
  s = (s || '').toString().trim();
  if (!s || /low activity/i.test(s)) return '';

  // نبحث عن dash (أي نوع) ثم آخر وقت
  const parts = s.split(/\s*[-–—−]\s*/); // أضفت − (minus sign)
  if (parts.length < 2) return '';

  const last = parts[parts.length - 1].trim();
  const m = last.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?/i);
  if (!m) return '';

  let hour = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const ampm = (m[3] || (last.match(/\b(AM|PM)\b/i)?.[1]) || '').toUpperCase();

  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;

  return String(hour).padStart(2,'0') + ':' + String(min).padStart(2,'0');
}

function extractSecondWindow(s) {
  s = (s || '').toString().trim();
  if (!s) return { start: '', end: '' };

  const parts = s.split(',');
  if (parts.length < 2) return { start: '', end: '' };

  const secondPart = parts[1].trim(); // "11:00 AM - 03:00 PM"

  return {
    start: extractStartHHMM(secondPart),
    end: extractEndHHMM(secondPart)
  };
}

